stage.title("A pyramid of cannonballs")
def tri(n, x):
    return VGroup(*[Dot(np.array([x + (j - i / 2) * 0.4, 1 - i * 0.35, 0]), radius=0.14, color=GREY_B) for i in range(n) for j in range(i + 1)])
layers = VGroup(*[tri(n, x) for n, x in ((1, -4.5), (2, -2.5), (3, 0), (4, 3))])
stage.play(LaggedStart(*[FadeIn(l) for l in layers], lag_ratio=0.3))
stage.add(layers)
for l, c in zip(layers, (1, 3, 6, 10)):
    stage.label(l, str(c), direction=DOWN)
